import hashlib
import redis
from sentence_transformers import SentenceTransformer

class TieredSemanticCache:
 def __init__(self, host="localhost", port=6379, threshold=0.94):
 self.r = redis.Redis(host=host, port=port, decode_responses=False)
 self.encoder = SentenceTransformer("all-MiniLM-L6-v2")
 self.threshold = threshold

 def get(self, query: str) -> str | None:
 # L1: Exact SHA-256 match
 q_hash = hashlib.sha256(query.strip().lower().encode()).hexdigest()
 exact = self.r.get(f"exact:{q_hash}")
 if exact:
 return exact.decode("utf-8")
 # L2: Cosine vector search
 return None

 def set(self, query: str, response: str):
 q_hash = hashlib.sha256(query.strip().lower().encode()).hexdigest()
 self.r.setex(f"exact:{q_hash}", 3600, response.encode("utf-8"))

import secrets

class HoneytokenTripwire:
 def __init__(self):
 self.active_canaries = set()

 def generate_token(self) -> str:
 token = f"CANARY_{secrets.token_hex(8).upper()}"
 self.active_canaries.add(token)
 return token

 def inspect_egress_payload(self, tool_name: str, payload: dict) -> bool:
 raw_str = str(payload)
 for canary in list(self.active_canaries):
 if canary in raw_str:
 raise RuntimeError(f"CRITICAL: Honeytoken leak in egress tool '{tool_name}'. Session severed.")
 return True

from dataclasses import dataclass
from typing import List, Dict, Any
import time

@dataclass
class AgentEvent:
 step_index: int
 action_type: str
 payload: Dict[str, Any]
 timestamp: float = time.time()

class EventSourcedAgentState:
 def __init__(self):
 self.event_stream: List[AgentEvent] = []

 def append_event(self, action_type: str, payload: Dict[str, Any]):
 event = AgentEvent(len(self.event_stream), action_type, payload)
 self.event_stream.append(event)

 def rollback_to_step(self, target_step: int):
 self.event_stream = self.event_stream[:target_step + 1]
